import urlMap from "../data/url-map.json"

// Posts moved to the new blog (https://amaran-th.vercel.app), keyed by their
// path here without slashes. Generated by the new blog's migration script.
const byPath = new Map(
  Object.entries(urlMap).map(([path, { newUrl }]) => [path.normalize("NFC"), newUrl])
)

export const newBlogUrl = pathname => {
  if (!pathname) return undefined
  let path = pathname
  try {
    path = decodeURIComponent(pathname)
  } catch {}
  return byPath.get(path.replace(/^\/+|\/+$/g, "").normalize("NFC"))
}
